import pandas as pd
from pandas import Series

TARGET = 10000000000000003

def dtype_dev(res, dtype):
    return 0.0 if str(res.dtype) == dtype else 1.0

def value_dev(res):
    try:
        return float(int(res.iloc[0]) - TARGET)
    except Exception:
        return 1e9

def na_dev(res):
    try:
        return 0.0 if pd.isna(res.iloc[1]) else 1.0
    except Exception:
        return 1e9

def measure(dtype, method):
    ser = Series([10000000000000001, None], dtype=dtype)
    fn = lambda x: x + 2 if pd.notna(x) else x
    res = ser.apply(fn) if method == "apply" else ser.map(fn)
    probe(dtype + "_" + method + "_dtype_dev", dtype_dev(res, dtype))
    probe(dtype + "_" + method + "_value_dev", value_dev(res))
    probe(dtype + "_" + method + "_na_dev", na_dev(res))

for dtype in ["Int64", "UInt64"]:
    for method in ["apply", "map"]:
        measure(dtype, method)

